def transform(grid):
    out=[row[:] for row in grid]
    mark=next((v for row in grid for v in row if v not in (0,1,2,3,4,5,6,8,9)), None)
    # The foreground is the unique non-binary color in these ARC inputs.
    if mark is None:
        colors={v for row in grid for v in row if v not in (0,1)}
        mark=next(iter(colors))
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==mark]
    minr=min(r for r,c in pts); maxr=max(r for r,c in pts); minc=min(c for r,c in pts); maxc=max(c for r,c in pts)
    shape={(r-minr,c-minc) for r,c in pts}
    H=maxr-minr+1; W=maxc-minc+1
    for r in range(len(grid)-H+1):
        for c in range(len(grid[0])-W+1):
            if all(grid[r+i][c+j]==0 for i,j in shape):
                for i,j in shape: out[r+i][c+j]=mark
    return out
